import java.util.*;

class Solution {
    public String[] sortPeople(String[] names, int[] heights) {
        Integer[] order = new Integer[names.length];
        for (int i = 0; i < order.length; i++) {
            order[i] = i;
        }

        Arrays.sort(order, (a, b) -> heights[b] - heights[a]);

        String[] answer = new String[names.length];
        for (int i = 0; i < order.length; i++) {
            answer[i] = names[order[i]];
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public String[] sortPeople(String[] names, int[] heights) {
        TreeMap<Integer, String> byHeight = new TreeMap<>(Collections.reverseOrder());
        for (int i = 0; i < names.length; i++) {
            byHeight.put(heights[i], names[i]);
        }

        String[] answer = new String[names.length];
        int index = 0;
        for (String name : byHeight.values()) {
            answer[index++] = name;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public String[] sortPeople(String[] names, int[] heights) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i = 0; i < names.length; i++) {
            heap.offer(new int[]{heights[i], i});
        }

        String[] answer = new String[names.length];
        int index = 0;
        while (!heap.isEmpty()) {
            answer[index++] = names[heap.poll()[1]];
        }
        return answer;
    }
}

class Solution {
    public String[] sortPeople(String[] names, int[] heights) {
        String[] byHeight = new String[100001];
        for (int i = 0; i < names.length; i++) {
            byHeight[heights[i]] = names[i];
        }

        String[] answer = new String[names.length];
        int index = 0;
        for (int height = byHeight.length - 1; height >= 0; height--) {
            if (byHeight[height] != null) {
                answer[index++] = byHeight[height];
            }
        }
        return answer;
    }
}
